ALTER TABLE "channels" ADD CONSTRAINT "channels_fase6_formats" CHECK (("channels"."tg_bot_id" is null or "channels"."tg_bot_id" ~ '^[0-9]{5,16}$') and ("channels"."tg_bot_username" is null or "channels"."tg_bot_username" ~ '^[A-Za-z0-9_]{1,64}$') and ("channels"."meta_page_id" is null or "channels"."meta_page_id" ~ '^[0-9]{5,32}$') and ("channels"."meta_ig_account_id" is null or "channels"."meta_ig_account_id" ~ '^[0-9]{5,32}$') and ("channels"."email_address" is null or char_length("channels"."email_address") between 3 and 254) and ("channels"."email_from_name" is null or char_length("channels"."email_from_name") between 1 and 100) and ("channels"."email_imap_host" is null or char_length("channels"."email_imap_host") between 1 and 253) and ("channels"."email_smtp_host" is null or char_length("channels"."email_smtp_host") between 1 and 253) and ("channels"."email_imap_username" is null or char_length("channels"."email_imap_username") between 1 and 255) and ("channels"."email_smtp_username" is null or char_length("channels"."email_smtp_username") between 1 and 255) and ("channels"."email_imap_folder" is null or char_length("channels"."email_imap_folder") between 1 and 200) and ("channels"."email_imap_port" is null or "channels"."email_imap_port" between 1 and 65535) and ("channels"."email_smtp_port" is null or "channels"."email_smtp_port" between 1 and 65535) and ("channels"."email_poll_interval_minutes" is null or "channels"."email_poll_interval_minutes" between 1 and 60) and ("channels"."email_imap_security" is null or "channels"."email_imap_security" in ('ssl', 'starttls')) and ("channels"."email_smtp_security" is null or "channels"."email_smtp_security" in ('ssl', 'starttls', 'none')) and ("channels"."email_smtp_mode" is null or "channels"."email_smtp_mode" in ('system', 'custom')) and ("channels"."email_trusted_auth_serv_ids" is null or (cardinality("channels"."email_trusted_auth_serv_ids") between 1 and 5 and array_to_string("channels"."email_trusted_auth_serv_ids", ',') ~ '^[a-z0-9.,-]{1,1300}$')) and cardinality("channels"."email_aliases") <= 20);--> statement-breakpoint
ALTER TABLE "messages" ADD CONSTRAINT "messages_email_recipient_valid" CHECK ("messages"."email_recipient" is null or ("messages"."direction" = 'inbound' and char_length("messages"."email_recipient") between 3 and 254));